# --------------------------------------------------------------------------- #
# config
# --------------------------------------------------------------------------- #
def load_yaml(path: Path) -> dict:
    if not path.exists():
        return {}
    try:
        with path.open() as fh:
            data = yaml.safe_load(fh)
    except yaml.YAMLError:
        return {}
    return data if isinstance(data, dict) else {}


def load_standard(raw) -> dict:
    """The harness standard in force: `harnesses.standard` over the module
    defaults. A control the contract does not list is OFF (that is how one is
    retired); a control id with no detector here is ignored, loudly."""
    raw = raw if isinstance(raw, dict) else {}
    routes = {rid: dict(spec) for rid, spec in DEFAULT_STANDARD["routes"].items()}
    for rid, spec in (raw.get("routes") or {}).items():
        if rid in routes and isinstance(spec, dict):
            routes[rid].update({k: spec[k] for k in ("standard", "title") if k in spec})
    listed = raw.get("controls")
    controls: dict = {}
    if isinstance(listed, dict):
        for cid, spec in listed.items():
            if cid not in DEFAULT_STANDARD["controls"]:
                sys.stderr.write(f"harnesses.standard: unknown control '{cid}' ignored "
                                 "(no detector in harness_registry.py)\n")
                continue
            base = dict(DEFAULT_STANDARD["controls"][cid])
            if isinstance(spec, dict):
                base.update({k: spec[k] for k in ("title", "rule") if spec.get(k)})
                if isinstance(spec.get("applies"), list):
                    base["applies"] = [k for k in spec["applies"] if k in ALL_KINDS]
            controls[cid] = base
    else:
        controls = {cid: dict(spec) for cid, spec in DEFAULT_STANDARD["controls"].items()}
    return {"version": raw.get("version", DEFAULT_STANDARD["version"]),
            "routes": routes, "controls": controls}


def load_config(fleet_path: Path) -> dict:
    fleet = load_yaml(fleet_path)
    cfg = fleet.get("harnesses") or {}
    hub = fleet.get("hub") or {}
    hub_nwo = hub.get("repo") or "bamr87/bamr87"
    # The account and organizations whose repos are the fleet's own — the same
    # list tools/fanout.sh writes to. A repo outside it is an external mirror.
    owners = [str(o) for o in (hub.get("owners") or []) if o] or [hub_nwo.split("/", 1)[0]]
    allowed = (fleet.get("ai_models") or {}).get("allowed") or {}
    models = sorted({str(m) for group in allowed.values() for m in (group or [])}
                    if isinstance(allowed, dict) else [])
    return {
        "hub_nwo": hub_nwo,
        "owners": owners,
        "allowed_models": models,
        "kit": cfg.get("kit", "agent-context"),
        "baseline": {**DEFAULT_BASELINE, **(cfg.get("baseline") or {})},
        "exempt": list(cfg.get("exempt") or []),
        "throughput": {**DEFAULT_THROUGHPUT, **(cfg.get("throughput") or {})},
        "budget": {**DEFAULT_BUDGET, **(cfg.get("budget") or {})},
        "inventory": {**DEFAULT_INVENTORY, **(cfg.get("inventory") or {})},
        "attention_max": int(cfg.get("attention_max") or DEFAULT_ATTENTION_MAX),
        "standard": load_standard(cfg.get("standard")),
    }


def hub_kit_version(path: Path = KIT_VERSION_FILE) -> str | None:
    """The kit version the fleet is graded against — read from the kit itself
    (templates/agent-context/VERSION), never duplicated into the contract."""
    try:
        for line in path.read_text().splitlines():
            if line.startswith("version:"):
                return line.split(":", 1)[1].strip()
    except OSError:
        pass
    return None


def _ver_tuple(v: str) -> tuple:
    parts = []
    for p in re.split(r"[.-]", v):
        parts.append(int(p) if p.isdigit() else 0)
    return tuple(parts or [0])


def kit_status(stamp: str | None, hub_version: str | None) -> str:
    """The stamp is the OBSERVABLE drift signal; whether an upgrade may be
    auto-applied stays fanout.sh's byte-compare decision (machine_seeded)."""
    if stamp is None:
        return "unstamped"
    if hub_version is None:
        return "unknown"
    a, b = _ver_tuple(stamp), _ver_tuple(hub_version)
    if a == b:
        return "current"
    return "upgradeable" if a < b else "ahead"


KIT_HANDLER_PATH = ".github/workflows/claude.yml"  # where the kit seeds its mention handler


def kit_shapes(version: str | None, repo_name: str = "", kit_dir: Path = KIT_DIR) -> dict[str, str]:
    """Every shape the kit has ever seeded its mention handler in, rendered the
    way tools/fanout.sh renders it (render_kit_template): text -> which shape.

    This is the fan-out's own `--upgrade` test, run at scan time. The stamp
    says which version a copy CLAIMS; only a byte comparison says whether the
    fan-out will replace it. A copy that carries a stamp but was edited by hand
    read as `upgradeable` for months, and its kit-drift finding could never be
    closed by the lever the finding named (bashcrawl, v0.4.0).
    """
    shapes: dict[str, str] = {}
    if not version:
        return shapes

    def render(path: Path) -> str | None:
        try:
            text = path.read_text(encoding="utf-8")
        except OSError:
            return None
        return (text.replace("__PROJECT_NAME__", repo_name)
                    .replace("__KIT_VERSION__", version))

    current = render(kit_dir / "claude.yml")
    if current is not None:
        shapes[current] = "current"
    archive = kit_dir / "archive"
    if archive.is_dir():
        for cand in sorted(archive.glob("claude-*.yml")):
            text = render(cand)
            if text is not None:
                shapes.setdefault(text, cand.name)
    return shapes


def kit_pristine(path: str, text: str, shapes: dict[str, str]) -> bool | None:
    """True when the file is byte-identical to a shape the kit seeded (so the
    fan-out may replace it), False when it has been edited, None when the file
    is not the kit's artifact or the kit could not be read."""
    if path != KIT_HANDLER_PATH or not shapes:
        return None
    return text in shapes


def upgradeable(h: dict) -> bool:
    """Would `fanout.sh --upgrade` replace this copy? A machine seed that is
    not the current shape: behind by its stamp, or an unstamped 0.1.0 seed.
    A scan from before `kit_pristine` existed falls back to the stamp alone."""
    pristine = h.get("kit_pristine")
    if pristine is False:
        return False
    if h.get("kit_status") == "upgradeable":
        return True
    return pristine is True and h.get("kit_status") == "unstamped"


_ROUTE_DEFAULTS: dict | None = None


def route_defaults() -> dict:
    """What the hub's two routes supply when a caller passes nothing: the
    dollar cap and the timeout, read from the files that define them so the
    inventory can never disagree with the lane it grades."""
    global _ROUTE_DEFAULTS
    if _ROUTE_DEFAULTS is not None:
        return _ROUTE_DEFAULTS
    out: dict = {"ai-lane": {}, "claude-run": {}}

    def number(value):
        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    lane = load_yaml(AI_LANE_FILE)
    on = lane.get("on", lane.get(True)) if lane else None
    inputs = ((on or {}).get("workflow_call") or {}).get("inputs") if isinstance(on, dict) else None
    if isinstance(inputs, dict):
        out["ai-lane"]["max_budget_usd"] = number((inputs.get("max-budget-usd") or {}).get("default"))
        out["ai-lane"]["timeout"] = number((inputs.get("timeout-minutes") or {}).get("default")) is not None
    action = load_yaml(CLAUDE_RUN_FILE)
    inputs = action.get("inputs") if action else None
    if isinstance(inputs, dict):
        out["claude-run"]["max_budget_usd"] = number((inputs.get("max-budget-usd") or {}).get("default"))
    _ROUTE_DEFAULTS = out
    return out


# --------------------------------------------------------------------------- #
# cron math (deterministic ESTIMATES — load planning, not fire prediction)
# --------------------------------------------------------------------------- #
def _parse_cron_field(field: str, lo: int, hi: int) -> set[int] | None:
    """One 5-field cron field -> the set of matching values, or None when the
    field is unparseable (names, L/W/# extensions). Numeric Vixie subset only:
    `*`, steps, ranges, lists."""
    values: set[int] = set()
    for part in field.split(","):
        part = part.strip()
        step = 1
        if "/" in part:
            part, step_s = part.split("/", 1)
            if not step_s.isdigit() or int(step_s) < 1:
                return None
            step = int(step_s)
        if part == "*":
            start, end = lo, hi
        elif "-" in part:
            a, _, b = part.partition("-")
            if not (a.isdigit() and b.isdigit()):
                return None
            start, end = int(a), int(b)
        elif part.isdigit():
            # `N/step` means N through hi in Vixie cron; a bare `N` is just N.
            start = int(part)
            end = hi if step > 1 else start
        else:
            return None
        if start < lo or end > hi or start > end:
            return None
        values.update(range(start, end + 1, step))
    return values


def parse_cron(cron: str) -> dict | None:
    """Parse a 5-field cron into value sets. dow 7 normalizes to 0 (Sunday)."""
    fields = cron.split()
    if len(fields) != 5:
        return None
    minutes = _parse_cron_field(fields[0], 0, 59)
    hours = _parse_cron_field(fields[1], 0, 23)
    doms = _parse_cron_field(fields[2], 1, 31)
    months = _parse_cron_field(fields[3], 1, 12)
    dows = _parse_cron_field(fields[4], 0, 7)
    if None in (minutes, hours, doms, months, dows):
        return None
    dows = {d % 7 for d in dows}
    return {
        "minutes": minutes, "hours": hours, "doms": doms,
        "months": months, "dows": dows,
        "dom_restricted": doms != set(range(1, 32)),
        "dow_restricted": dows != set(range(0, 7)),
        "month_restricted": months != set(range(1, 13)),
    }


def cron_fires_per_day(cron: str) -> float | None:
    """Average fires per calendar day. Approximation, documented:
    a day-of-week restriction scales by k/7, a day-of-month one by k/30.44,
    and when BOTH are restricted Vixie semantics are OR — approximated as the
    capped sum. Good enough to compare standing load against a cap; not a
    scheduler."""
    p = parse_cron(cron)
    if p is None:
        return None
    per_matching_day = len(p["minutes"]) * len(p["hours"])
    if p["dow_restricted"] and p["dom_restricted"]:
        frac = min(1.0, len(p["dows"]) / 7 + len(p["doms"]) / AVG_DAYS_PER_MONTH)
    elif p["dow_restricted"]:
        frac = len(p["dows"]) / 7
    elif p["dom_restricted"]:
        frac = min(1.0, len(p["doms"]) / AVG_DAYS_PER_MONTH)
    else:
        frac = 1.0
    if p["month_restricted"]:
        frac *= len(p["months"]) / 12
    return round(per_matching_day * frac, 3)


def describe_cron(cron: str) -> str:
    """Short human summary for the calendar; falls back to the raw expression."""
    p = parse_cron(cron)
    if p is None:
        return cron
    if len(p["minutes"]) == 1 and len(p["hours"]) == 1:
        t = f"{next(iter(p['hours'])):02d}:{next(iter(p['minutes'])):02d}"
        if p["dow_restricted"] and len(p["dows"]) == 1:
            return f"{DAY_NAMES[next(iter(p['dows']))]} {t} UTC weekly"
        if p["dom_restricted"] and len(p["doms"]) == 1:
            return f"day {next(iter(p['doms']))} {t} UTC monthly"
        if not p["dow_restricted"] and not p["dom_restricted"]:
            return f"daily {t} UTC"
        return f"{t} UTC ({cron})"
    if len(p["hours"]) == 24 and len(p["minutes"]) == 1:
        return f"hourly at :{next(iter(p['minutes'])):02d}"
    if len(p["minutes"]) > 1 and len(p["hours"]) == 24:
        step = 60 // len(p["minutes"])
        if len(p["minutes"]) in (2, 3, 4, 6, 12) and p["minutes"] == set(range(0, 60, step)):
            return f"every {step} min"
    if len(p["hours"]) > 1 and len(p["minutes"]) == 1 and len(p["hours"]) in (2, 3, 4, 6, 8, 12):
        step = 24 // len(p["hours"])
        if p["hours"] == set(range(0, 24, step)):
            return f"every {step}h at :{next(iter(p['minutes'])):02d}"
    return cron


# --------------------------------------------------------------------------- #
# workflow classification (pure text -> facts; no network)
# --------------------------------------------------------------------------- #
def classify_workflow(path: str, text: str) -> dict:
    """Extract the inventory facts from one workflow file's content.

    Tolerant by design: an unparseable YAML file still yields the regex-visible
    facts (claude marker, crons) plus parse_error=True, because a fleet scan
    that dies on one repo's broken workflow reports nothing about the other 39.
    """
    # Routes are matched on the file without its comment lines: a workflow that
    # only mentions an action in a header is not a harness.
    code = COMMENT_LINE_RX.sub("", text)
    routes = [rid for rid, rx in AI_ROUTES if rx.search(code)]
    info: dict = {
        "path": path,
        "name": None,
        "triggers": [],
        "crons": [],
        "ai": bool(routes),
        "route": routes[0] if routes else None,
        "routes": routes,
        "parse_error": False,
    }
    data = None
    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError:
        info["parse_error"] = True
    if isinstance(data, dict):
        name = data.get("name")
        info["name"] = str(name) if name is not None else None
        # YAML 1.1 parses a bare `on:` key as boolean True.
        on = data.get("on", data.get(True))
        if isinstance(on, dict):
            info["triggers"] = sorted(str(k) for k in on)
            sched = on.get("schedule")
            if isinstance(sched, list):
                info["crons"] = [
                    str(e["cron"]).strip() for e in sched
                    if isinstance(e, dict) and e.get("cron")
                ]
        elif isinstance(on, list):
            info["triggers"] = sorted(str(t) for t in on)
        elif isinstance(on, str):
            info["triggers"] = [on]
    else:
        info["parse_error"] = info["parse_error"] or data is not None or not text.strip()
        info["crons"] = CRON_FALLBACK_RX.findall(text)
        if "schedule" in text and info["crons"]:
            info["triggers"] = ["schedule"]
    if info["name"] is None:
        info["name"] = Path(path).stem
    # A compiled GitFactory line announces itself in its header, with the
    # blueprint it was compiled from and that blueprint's hash; a kill switch
    # is any repo variable named *_ENABLED the workflow reads (the `gate` job
    # pattern: an unset variable reads as idle, never as "safe to run").
    if FACTORY_HEADER_RX.search(text):
        bp = FACTORY_BLUEPRINT_RX.search(text)
        h = FACTORY_HASH_RX.search(text)
        info["factory"] = {"blueprint": bp.group(1) if bp else None,
                           "hash": h.group(1) if h else None}
    else:
        info["factory"] = None
    m = SWITCH_RX.search(code) or INPUT_SWITCH_RX.search(code)
    info["switch"] = m.group(1) if m else None
    if info["ai"]:
        route = info["route"]
        hub_route = route in ("ai-lane", "claude-run")
        defaults = route_defaults().get(route) or {}
        m = ACTION_REF_RX.search(code)
        info["action_ref"] = m.group(1) if m else None
        # `ordered` = the credential comes from the repo's CLAUDE_AUTH_ORDER
        # (the claude-auth step, or the hub runner reading it) — the order is
        # then configuration in ai_auth:, not a property of the file.
        if route == "claude-code-action":
            has_oauth = "claude_code_oauth_token" in text
            has_key = "anthropic_api_key" in text
            ordered = "claude-auth@" in text or "CLAUDE_AUTH_ORDER" in text
        elif hub_route:
            has_oauth = has_key = ordered = True  # run.sh takes both, in the repo's order
        elif route == "other-provider":
            has_oauth, has_key, ordered = False, True, False
        else:
            has_oauth = "CLAUDE_CODE_OAUTH_TOKEN" in code
            has_key = "ANTHROPIC_API_KEY" in code
            ordered = "CLAUDE_AUTH_ORDER" in code or "AI_AUTH_ORDER" in code
        info["auth"] = (
            "ordered" if ordered and (has_oauth or has_key)
            else "oauth-first" if has_oauth and has_key
            else "oauth-only" if has_oauth
            else "api-key" if has_key
            else "none"
        )
        m = (INPUT_MODEL_RX.search(code) if hub_route else None) or MODEL_RX.search(code)
        info["model"] = m.group(1) if m else None
        # A hub route with no model named resolves one itself (the consumer's
        # _data/ai.yml, else the runner's pinned fleet default); anything else
        # with no model takes whatever its tool's default is that day.
        info["model_source"] = ("literal" if m else "expression" if MODEL_EXPR_RX.search(code)
                                else "route" if hub_route else "none")
        m = MAX_TURNS_RX.search(code) or (INPUT_TURNS_RX.search(code) if hub_route else None)
        info["max_turns"] = int(m.group(1)) if m else None
        m = MAX_BUDGET_RX.search(code)
        info["max_budget_usd"] = float(m.group(1)) if m else defaults.get("max_budget_usd")
        m = KIT_STAMP_RX.search(text)
        info["kit"] = m.group(1) if m else None
        # A prose "@claude" in a header comment must not read as a handler —
        # only a workflow that can actually RECEIVE a mention counts.
        mention_triggers = {"issue_comment", "issues",
                            "pull_request_review", "pull_request_review_comment"}
        info["mention_handler"] = (
            "@claude" in text and bool(mention_triggers & set(info["triggers"]))
        )
        info["kind"] = (
            "scheduled-agent" if info["crons"]
            else "mention-handler" if info["mention_handler"]
            else "event-agent"
        )
        # The facts the standard grades. `author_gate` is None when no trigger
        # lets a stranger start the run, so there is nothing to gate.
        open_triggers = UNTRUSTED_TRIGGERS & set(info["triggers"])
        info["author_gate"] = bool(AUTHOR_GATE_RX.search(code)) if open_triggers else None
        info["least_privilege"] = _least_privilege(data, code)
        info["timeout"] = bool(TIMEOUT_RX.search(code)) or bool(defaults.get("timeout"))
    return info


def _least_privilege(data, code: str) -> bool:
    """A top-level `permissions:` block, and `write-all` nowhere."""
    if isinstance(data, dict):
        top = data.get("permissions")
        if top is None or top == "write-all":
            return False
        jobs = data.get("jobs")
        if isinstance(jobs, dict):
            return not any(isinstance(j, dict) and j.get("permissions") == "write-all"
                           for j in jobs.values())
        return True
    return bool(re.search(r"^permissions:", code, re.M)) and "write-all" not in code


# --------------------------------------------------------------------------- #
# the harness standard (facts -> verdict -> lever; pure)
# --------------------------------------------------------------------------- #
def harness_id(repo_name: str, path: str) -> str:
    """The id _data/agents.yml gives the same workflow, so the two files join."""
    return f"ci:{repo_name}:{Path(path).name.rsplit('.', 1)[0]}"


def is_pinned(model, allowed: list[str]) -> bool:
    """An exact model id, not an alias. With the allowlist in hand the model
    must be on it; without it (no fleet.yml) an id that carries a version."""
    if not model:
        return False
    if allowed:
        return model in allowed
    return bool(re.search(r"-\d", str(model)))


def _fires_on_the_hour(cron: str) -> bool:
    parsed = parse_cron(cron)
    return parsed is None or 0 in parsed["minutes"]


# One detector per control: True (met), False (missing), None (nothing here for
# the control to bind — a workflow no stranger can trigger has no author gate
# to check). Each reads only facts the scan stored, so a reused scan grades
# the same way a live one does.
def _started_by_hand(h: dict) -> bool:
    """Only a person pressing a button, or a caller workflow, starts it. A
    kill switch is bypassed by a manual dispatch by design (AGENTS.md), and a
    called workflow is gated at its call site, so there is no standing run for
    a switch to stop."""
    triggers = set(h.get("triggers") or [])
    return bool(triggers) and triggers <= {"workflow_dispatch", "workflow_call"}


def _called_only(h: dict) -> bool:
    """A reusable workflow with no trigger of its own: it runs under its
    caller's permissions, which is where least privilege is declared."""
    return set(h.get("triggers") or []) == {"workflow_call"}


def _model_pinned(h: dict, cfg: dict):
    if h.get("model"):
        return is_pinned(h["model"], cfg["allowed_models"])
    source = h.get("model_source")
    if source == "expression":
        return None  # decided at run time; not readable from the file
    return source == "route"  # the hub runner resolves a pinned model itself


CONTROL_CHECKS = {
    "standard-route": lambda h, cfg: bool(
        (cfg["standard"]["routes"].get(h.get("route")) or {}).get("standard")),
    "model-pinned": _model_pinned,
    "budget-cap": lambda h, cfg: h.get("max_budget_usd") is not None,
    "turn-cap": lambda h, cfg: h.get("max_turns") is not None,
    "kill-switch": lambda h, cfg: None if _started_by_hand(h) else bool(h.get("switch")),
    "auth-ordered": lambda h, cfg: (
        None if h.get("route") == "other-provider" else h.get("auth") == "ordered"),
    "trusted-author": lambda h, cfg: h.get("author_gate"),
    "least-privilege": lambda h, cfg: (
        None if _called_only(h) else bool(h.get("least_privilege"))),
    "timeout": lambda h, cfg: bool(h.get("timeout")),
    "off-hour-cron": lambda h, cfg: (
        not any(_fires_on_the_hour(c) for c in h["crons"]) if h.get("crons") else None),
}


def grade_harness(h: dict, cfg: dict) -> dict | None:
    """One harness against the standard. None when the row predates the facts
    the standard reads (a reused scan from before `route` was recorded): an
    ungraded harness says so instead of failing controls nobody looked at."""
    if not h.get("route"):
        return None
    met, missing = 0, []
    for cid, spec in cfg["standard"]["controls"].items():
        if h.get("kind") not in (spec.get("applies") or []):
            continue
        verdict = CONTROL_CHECKS[cid](h, cfg)
        if verdict is None:
            continue
        if verdict:
            met += 1
        else:
            missing.append(cid)
    return {"conformant": not missing, "met": met, "of": met + len(missing), "missing": missing}


def is_retired(repo: dict) -> bool:
    """An archived repo's workflows never run: GitHub disables Actions on it."""
    return bool(repo.get("archived")) or repo.get("status") == "archived"


def choose_lever(h: dict, repo: dict, cfg: dict) -> str | None:
    """How this harness is rebuilt onto the standard — the first that fits."""
    if is_retired(repo):
        return "retire"
    verdict = h.get("standard")
    if not verdict:
        return None
    ok = verdict["conformant"]
    if h.get("factory"):
        return "none" if ok else "factory-recompile"
    if repo.get("nwo") == cfg["hub_nwo"]:
        return "none" if ok else "hub-fix"
    if h.get("path") == KIT_HANDLER_PATH and (h.get("kit") or h.get("kit_pristine")):
        if upgradeable(h):
            return "kit-upgrade"
        if h.get("kit_pristine") is False:
            return "none" if ok else "kit-adopt"
        # the current shape, untouched: if it still misses a control the kit
        # itself does, and the next kit release reaches it by upgrade
        return "none" if ok else "kit-upgrade"
    if ok:
        return "none"
    if h.get("kind") == "mention-handler":
        return "kit-adopt"
    if h.get("route") in ("ai-lane", "claude-run"):
        return "fix-controls"
    return "lane-adopt"


def build_catalog(repos: list[dict], cfg: dict) -> dict:
    """The organized view: every live harness counted by kind, route and lever,
    and how many miss each control. Rows stay under `repos[].harnesses[]`; the
    catalog is the index over them."""
    live = [(r, h) for r in repos if not is_retired(r) for h in r.get("harnesses") or []]
    graded = [(r, h) for r, h in live if h.get("standard")]
    by_kind: dict = {}
    for kind in ALL_KINDS:
        rows = [h for _, h in live if h.get("kind") == kind]
        by_kind[kind] = {
            "harnesses": len(rows),
            "conformant": sum(1 for h in rows if (h.get("standard") or {}).get("conformant")),
        }
    by_route = {rid: sum(1 for _, h in live if h.get("route") == rid) for rid in ROUTE_IDS}
    by_lever = {lid: 0 for lid in LEVERS}
    for r in repos:
        for h in r.get("harnesses") or []:
            if h.get("lever") in by_lever:
                by_lever[h["lever"]] += 1
    missing = {cid: 0 for cid in cfg["standard"]["controls"]}
    for _, h in graded:
        for cid in h["standard"]["missing"]:
            if cid in missing:
                missing[cid] += 1
    return {
        "harnesses": len(live),
        "graded": len(graded),
        "conformant": sum(1 for _, h in graded if h["standard"]["conformant"]),
        "retired": sum(len(r.get("harnesses") or []) for r in repos if is_retired(r)),
        "by_kind": by_kind,
        "by_route": {rid: n for rid, n in by_route.items() if n},
        "by_lever": {lid: n for lid, n in by_lever.items() if n},
        "missing_by_control": missing,
        "levers": {lid: dict(spec) for lid, spec in LEVERS.items()},
    }


# --------------------------------------------------------------------------- #
# joins (committed ledgers -> per-repo / per-harness numbers; pure)
# --------------------------------------------------------------------------- #
def rotation_secret_states(rotation: dict, name: str = "CLAUDE_CODE_OAUTH_TOKEN") -> dict[str, str]:
    """nwo -> the secret's state AFTER the rotation run (harness.rotation_repo_state):
    an applied `written` repo holds the secret even when an old-shape ledger still
    carries the `missing` its survey saw before the write."""
    mode = rotation.get("mode")
    for token in rotation.get("tokens") or []:
        if isinstance(token, dict) and token.get("name") == name:
            return {
                r.get("nwo"): str(harness.rotation_repo_state(r, mode)[0])
                for r in token.get("repos") or []
                if isinstance(r, dict) and r.get("nwo")
            }
    return {}


def join_usage(repos: list[dict], ai_usage: dict, actions_usage: dict) -> None:
    """Annotate scan rows in place with the committed ledgers' numbers. The
    windows are whatever those ledgers carry — echoed, never recomputed here."""
    ai_by_repo = {r.get("repo"): r for r in ai_usage.get("by_repo") or [] if isinstance(r, dict)}
    ai_by_wf = {
        w.get("workflow"): w for w in ai_usage.get("by_workflow") or [] if isinstance(w, dict)
    }
    act_by_path = {
        (w.get("repo"), w.get("path")): w
        for w in actions_usage.get("workflows") or []
        if isinstance(w, dict)
    }
    for repo in repos:
        a = ai_by_repo.get(repo.get("repo"))
        if a:
            repo["ai_usage"] = {
                "runs": a.get("runs"),
                "cost_usd": a.get("cost_usd"),
                "est_cost_usd": a.get("est_cost_usd"),
                "accounted_usd": a.get("accounted_usd"),
                "minutes": a.get("minutes"),
                "priced_runs": a.get("priced_runs"),
                "unpriced_runs": a.get("unpriced_runs"),
                "no_spend_runs": a.get("no_spend_runs"),
            }
        else:
            repo["ai_usage"] = None
        for h in repo.get("harnesses") or []:
            wf_key = f"{repo.get('repo')}/{h.get('workflow')}"
            u = ai_by_wf.get(wf_key)
            h["cost_usd_window"] = u.get("cost_usd") if u else None
            h["runs_window"] = u.get("runs") if u else None
            act = act_by_path.get((repo.get("repo"), h.get("path")))
            if act:
                h["last_conclusion"] = act.get("last_conclusion")
                h["flags"] = act.get("flags") or []
                if h.get("runs_window") is None:
                    h["runs_window"] = act.get("runs")
            else:
                h.setdefault("last_conclusion", None)
                h.setdefault("flags", [])


def evaluate_coverage(repo: dict, cfg: dict) -> None:
    """Grade one repo against the baseline. External upstreams, archived repos,
    unscanned rows, and explicit exemptions are excused, not failed."""
    baseline = cfg["baseline"]
    excused = (
        repo.get("external")
        or repo.get("archived")
        or not repo.get("scanned")
        or repo.get("status") == "archived"
        or repo.get("repo") in cfg["exempt"]
    )
    missing: list[str] = []
    if not excused:
        if baseline.get("require_mention_handler") and not any(
            h.get("mention_handler") for h in repo.get("harnesses") or []
        ):
            missing.append("mention-handler")
        if baseline.get("require_agent_context") and not repo.get("agent_context"):
            missing.append("agent-context")
        if baseline.get("require_oauth_secret") and repo.get("oauth_secret") in ("missing",):
            missing.append("oauth-secret")
    repo["coverage"] = {"exempt": bool(excused), "ok": not missing, "missing": missing}


def repo_schedule_load(repo: dict) -> float:
    """Estimated cron-driven AI workflow runs/day for one repo. An archived
    repo contributes nothing: its crons are still in the files, but GitHub
    never fires them, and counting them spent throughput the fleet did not use."""
    if is_retired(repo):
        return 0.0
    parts = [cron_fires_per_day(cron) or 0.0
             for h in repo.get("harnesses") or []
             for cron in h.get("crons") or []]
    return round(math.fsum(parts), 3)


def build_throughput(repos: list[dict], cfg: dict, ai_usage: dict) -> dict:
    caps = cfg["throughput"]
    # fsum, not sum: the per-repo estimates are floats whose plain left-to-right
    # total lands on rounding knife-edges (10.605 → 10.6 or 10.61 depending on
    # repo order), which churned this committed file on every daily refresh.
    fleet_est = round(math.fsum(r.get("est_scheduled_ai_per_day") or 0 for r in repos), 2)
    over_repo = [
        {"repo": r["repo"], "est_per_day": r["est_scheduled_ai_per_day"],
         "cap": caps["max_scheduled_ai_per_day_repo"]}
        for r in repos
        if (r.get("est_scheduled_ai_per_day") or 0) > caps["max_scheduled_ai_per_day_repo"]
    ]
    # UTC-hour adjacency: only single-shot AI crons (fixed hour set) count —
    # an hourly agent is a per-repo/fleet cap problem, not an adjacency one.
    hour_load: dict[int, list[str]] = {}
    for r in repos:
        if is_retired(r):
            continue
        for h in r.get("harnesses") or []:
            for cron in h.get("crons") or []:
                p = parse_cron(cron)
                if p is None or len(p["hours"]) > 3:
                    continue
                for hour in p["hours"]:
                    hour_load.setdefault(hour, []).append(f"{r['repo']}:{h['workflow']}")
    collisions = [
        {"utc_hour": f"{hour:02d}:00", "count": len(entries), "entries": sorted(entries)}
        for hour, entries in sorted(hour_load.items())
        if len(entries) > caps["max_ai_crons_per_utc_hour"]
    ]
    observed = None
    totals = ai_usage.get("totals") or {}
    window = ai_usage.get("window_days")
    if totals.get("ci_runs") is not None and window:
        observed = round(totals["ci_runs"] / float(window), 1)
    return {
        "est_scheduled_ai_per_day": fleet_est,
        "cap_fleet": caps["max_scheduled_ai_per_day_fleet"],
        "fleet_over_cap": fleet_est > caps["max_scheduled_ai_per_day_fleet"],
        "observed_ai_runs_per_day": observed,  # all triggers, from ai_usage.yml
        "repos_over_cap": over_repo,
        "hour_collisions": collisions,
        "cap_per_repo": caps["max_scheduled_ai_per_day_repo"],
        "cap_per_utc_hour": caps["max_ai_crons_per_utc_hour"],
    }


def _series_trend(series: list[tuple[str, float]], budget_monthly: float | None,
                  warn_pct: float) -> dict:
    """Window totals, week-over-week delta, and a projected monthly figure from
    one (day, value) series. Projection = last-7-day daily average × 30.44,
    falling back to the whole window when the series is shorter."""
    days = sorted(series)
    total = round(math.fsum(v for _, v in days), 2)
    out: dict = {
        "window_total": total,
        "daily_avg": round(total / len(days), 3) if days else None,
        "last7": None, "prior7": None, "wow_delta_pct": None,
        "projected_monthly": None,
        "budget_monthly": budget_monthly,
        "status": "no-data",
    }
    if not days:
        return out
    last_day = dt.date.fromisoformat(days[-1][0])
    cut7 = (last_day - dt.timedelta(days=6)).isoformat()
    cut14 = (last_day - dt.timedelta(days=13)).isoformat()
    last7 = round(math.fsum(v for d, v in days if d >= cut7), 2)
    prior7 = round(math.fsum(v for d, v in days if cut14 <= d < cut7), 2)
    out["last7"] = last7
    out["prior7"] = prior7
    if prior7 > 0:
        out["wow_delta_pct"] = round(100.0 * (last7 - prior7) / prior7, 1)
    daily = last7 / 7.0 if last7 or prior7 else (total / len(days))
    out["projected_monthly"] = round(daily * AVG_DAYS_PER_MONTH, 2)
    if budget_monthly is not None and out["projected_monthly"] > budget_monthly:
        out["status"] = "breach"
    elif out["wow_delta_pct"] is not None and out["wow_delta_pct"] > warn_pct:
        out["status"] = "growing"
    else:
        out["status"] = "ok"
    return out


def _apply_billing(trend: dict, billing: dict, budget_monthly, warn_pct: float) -> dict:
    """Price Actions from GitHub's meter instead of the wall-clock proxy.

    The proxy's projection is kept as `proxy_projected_monthly` so the two can
    be compared on the page, but status is judged on billed minutes only: the
    proxy once projected 287k min/month against ~24k billed and parked a
    phantom `budget-breach` at the top of the attention queue for a fortnight
    (2026-09 review). Projection = this month's run-rate once a week of it
    exists, else the last full month; growth is month-over-month, since a
    month is the meter's grain.
    """
    out = dict(trend)
    out["proxy_projected_monthly"] = trend.get("projected_monthly")
    out["source"] = "billing"
    out["billed_this_month"] = billing.get("minutes_this_month")
    out["billed_previous_month"] = billing.get("minutes_previous_month")
    rate, prev = billing.get("run_rate_monthly"), billing.get("minutes_previous_month")
    projected = rate if (rate is not None and (billing.get("days_elapsed") or 0) >= 7) else prev
    if projected is None:
        projected = rate
    out["projected_monthly"] = round(projected, 2) if projected is not None else None
    out["mom_delta_pct"] = (round(100.0 * (out["projected_monthly"] - prev) / prev, 1)
                            if prev and out["projected_monthly"] is not None else None)
    if out["projected_monthly"] is None:
        out["status"] = "no-data"
    elif budget_monthly is not None and out["projected_monthly"] > budget_monthly:
        out["status"] = "breach"
    elif out["mom_delta_pct"] is not None and out["mom_delta_pct"] > warn_pct:
        out["status"] = "growing"
    else:
        out["status"] = "ok"
    return out


def ai_day_cost(row: dict) -> float:
    """What one day of Claude CI cost the fleet: measured spend PLUS the stated
    estimate for the runs that left no usage behind (`accounted_usd`).

    Judging the ceiling on the measured half alone is how a fleet whose runs
    were 87% unpriced read as $1.03 against a $75/month budget. A ledger
    written before the estimator existed has no `accounted_usd`, so the
    measured figure is still honoured as the whole.
    """
    if row.get("accounted_usd") is not None:
        return float(row["accounted_usd"] or 0)
    return float(row.get("cost_usd") or 0) + float(row.get("est_cost_usd") or 0)


def build_trends(ai_usage: dict, actions_usage: dict, cfg: dict) -> dict:
    budget = cfg["budget"]
    ai_days = [r for r in ai_usage.get("by_day") or []
               if isinstance(r, dict) and r.get("day")]
    ai_series = [(str(r.get("day")), ai_day_cost(r)) for r in ai_days]
    act_series = [
        (str(r.get("date")), float(r.get("total_min") or 0))
        for r in actions_usage.get("by_day") or [] if isinstance(r, dict) and r.get("date")
    ]
    actions = _series_trend(act_series, budget.get("monthly_actions_minutes"),
                            budget["trend_warn_pct"])
    billing = actions_usage.get("billing")
    if isinstance(billing, dict) and not billing.get("error"):
        actions = _apply_billing(actions, billing, budget.get("monthly_actions_minutes"),
                                 budget["trend_warn_pct"])
    ai = _series_trend(ai_series, budget.get("monthly_ai_usd"),
                       budget["trend_warn_pct"])
    # State the confidence beside the number: how much of the window was
    # measured, and how much is the estimator's.
    measured = round(math.fsum(float(r.get("cost_usd") or 0) for r in ai_days), 2)
    estimated = round(math.fsum(float(r.get("est_cost_usd") or 0) for r in ai_days), 2)
    ai["measured_total"] = measured
    ai["estimated_total"] = estimated
    ai["estimated_share_pct"] = (round(100.0 * estimated / (measured + estimated), 1)
                                 if (measured + estimated) else 0.0)
    ai["cost_basis"] = "measured+estimated" if estimated else "measured"
    return {
        "ai_cost_usd": ai,
        "actions_minutes": actions,
    }


# --------------------------------------------------------------------------- #
# attention (ranked findings — observations with the lever named, never writes)
# --------------------------------------------------------------------------- #
def build_attention(repos: list[dict], throughput: dict, trends: dict, cfg: dict,
                    catalog: dict | None = None) -> list[dict]:
    items: list[dict] = []

    def add(severity: int, kind: str, summary: str, action: str, repo: str | None = None,
            lever: str | None = None):
        row = {"severity": severity, "kind": kind, "summary": summary, "action": action}
        if repo:
            row["repo"] = repo
        if lever:
            row["lever"] = lever
        items.append(row)

    for key, label, unit in (("ai_cost_usd", "Claude CI spend", "USD"),
                             ("actions_minutes", "Actions minutes", "min")):
        t = trends.get(key) or {}
        if t.get("status") == "breach":
            add(90, "budget-breach",
                f"projected monthly {label} {t['projected_monthly']} {unit} exceeds the "
                f"{t['budget_monthly']} {unit} ceiling",
                "retune the loops' cadence/caps, or raise harnesses.budget in _data/fleet.yml")
        elif t.get("status") == "growing":
            if t.get("source") == "billing":
                grew = (f"{t['mom_delta_pct']}% month-over-month (billed {t['billed_previous_month']} "
                        f"{unit} last month, {t['projected_monthly']} {unit} projected)")
            else:
                grew = f"{t['wow_delta_pct']}% week-over-week (last 7d: {t['last7']} {unit})"
            add(50, "cost-trend", f"{label} grew {grew}",
                "check /harnesses/ trends and the actions/ai-usage boards for the driver")

    if throughput.get("fleet_over_cap"):
        add(85, "throughput-fleet",
            f"estimated scheduled AI runs/day {throughput['est_scheduled_ai_per_day']} exceeds "
            f"the fleet cap {throughput['cap_fleet']}",
            "retire or slow a cron, or raise harnesses.throughput in _data/fleet.yml")
    for v in throughput.get("repos_over_cap") or []:
        add(80, "throughput-repo",
            f"estimated scheduled AI runs/day {v['est_per_day']} exceeds the per-repo cap {v['cap']}",
            "retune that repo's agent crons", repo=v["repo"])
    for c in throughput.get("hour_collisions") or []:
        add(70, "schedule-collision",
            f"{c['count']} AI crons share {c['utc_hour']} UTC: {', '.join(c['entries'][:6])}",
            "stagger the crons — the Claude loops share one OAuth account's rate limit")

    # The rebuild plan, one finding per lever rather than one per harness: what
    # the fleet's harnesses still miss against the standard, grouped by the
    # action that fixes the group.
    for lever, count in ((catalog or {}).get("by_lever") or {}).items():
        if lever == "none" or not count:
            continue
        rows = [h for r in repos for h in r.get("harnesses") or [] if h.get("lever") == lever]
        tally: dict[str, int] = {}
        for h in rows:
            for cid in (h.get("standard") or {}).get("missing") or []:
                tally[cid] = tally.get(cid, 0) + 1
        top = ", ".join(f"{cid} ({n})" for cid, n in
                        sorted(tally.items(), key=lambda kv: (-kv[1], kv[0]))[:4])
        what = (f"{count} harness(es) in archived repos still listed" if lever == "retire"
                else f"{count} harness(es) off the standard — missing {top}" if top
                else f"{count} harness(es) behind the current kit")
        add(48 if lever != "retire" else 30, "standard-gap",
            f"{LEVERS[lever]['title']}: {what}", LEVERS[lever]["action"], lever=lever)

    for r in repos:
        if r.get("workflows_truncated"):
            add(66, "inventory-truncated",
                f"only {r.get('workflows_total')} of {r.get('workflows_listed')} workflow files were "
                "read, so harnesses past the cap are not in this inventory",
                "raise harnesses.inventory.max_workflow_files in _data/fleet.yml", repo=r["repo"])
        if is_retired(r):
            continue  # nothing in an archived repo runs, fails or drifts
        for h in r.get("harnesses") or []:
            if h.get("last_conclusion") == "failure" or "failing" in (h.get("flags") or []):
                add(75, "harness-failing",
                    f"{h['path']} last run failed",
                    "the fleet-pulse doctor queue owns the fix; see the Inbox (/inbox)", repo=r["repo"])
            if h.get("auth") in ("api-key", "none"):
                add(60, "auth-drift",
                    f"{h['path']} auth is '{h['auth']}' (house convention: the ordered "
                    f"claude-auth step, or OAuth-first)",
                    "dispatch fanout.yml (kit: harness) with upgrade, or align the call site by hand",
                    repo=r["repo"])
        cov = r.get("coverage") or {}
        for gap in cov.get("missing") or []:
            if gap == "oauth-secret":
                add(65, "coverage-gap",
                    "CLAUDE_CODE_OAUTH_TOKEN missing (per the rotation ledger)",
                    "token-rotation.yml enrols it weekly; `dash secrets rotate --apply` does it now",
                    repo=r["repo"])
            else:
                add(58 if gap == "mention-handler" else 55, "coverage-gap",
                    f"baseline artifact missing: {gap}",
                    "dispatch fanout.yml (kit: harness, target: gaps), or `dash harnesses deploy --gaps`",
                    repo=r["repo"])
        # `gap-not-deployable` used to live here: a gap the kit could close on a
        # repo the fan-out could not reach, because fanout.sh resolved --target
        # through .gitmodules alone and every registry-only repo was a dead end
        # (that is how bamr87/SCHEMA — the upstream of the linter this hub
        # vendors — sat months without a mention handler). The engine now falls
        # back to the registry, which leaves the class EMPTY rather than
        # smaller: everything still unreachable (external upstream, archived) is
        # already excused by evaluate_coverage and so has no gap to report. A
        # finding that cannot fire is worse than no finding, so it is gone.
        # Only a copy the fan-out will actually replace: a stamped copy that
        # was edited by hand is the kit-adopt lever's, not a drift the upgrade
        # can close.
        behind = [h["path"] for h in r.get("harnesses") or [] if upgradeable(h)]
        if behind:
            add(40, "kit-drift",
                f"machine-seeded harness behind the current kit: {', '.join(behind)}",
                "dispatch fanout.yml (kit: harness) with upgrade=true (byte-identical seeds only)",
                repo=r["repo"])
        # A scheduled agent is a standing commitment; without a repo-variable
        # kill switch the only way to stop it is a commit to its workflow.
        # Mention handlers are excused — they run only when asked.
        unswitched = [h["path"] for h in r.get("harnesses") or []
                      if h.get("kind") == "scheduled-agent" and not h.get("switch")]
        if unswitched:
            add(45, "switch-missing",
                f"scheduled agent without a vars.*_ENABLED kill switch: {', '.join(unswitched)}",
                "gate the line on a repo variable (GitFactory's `gate` job pattern) so it can be "
                "disarmed without a commit",
                repo=r["repo"])

    items.sort(key=lambda i: (-i["severity"], i.get("repo") or "", i["kind"]))
    return items[: cfg["attention_max"]]


# --------------------------------------------------------------------------- #
# fleet scan (the network half)
# --------------------------------------------------------------------------- #
def scan_repo(gh, project: dict, cfg: dict, secret_states: dict[str, str],
              hub_version: str | None) -> dict:
    name = project.get("name")
    nwo = actions_analytics.owner_repo(project.get("repo_url", ""))
    row: dict = {
        "repo": name,
        "nwo": nwo,
        "category": project.get("category"),
        "status": project.get("status"),
        "external": is_external(nwo, cfg),
        # fanout.sh resolves a --target through .gitmodules, so a registry repo
        # with no submodule_path cannot be deployed to no matter what its
        # coverage says. Recorded here so the board and `--gaps` agree.
        "submodule": bool(project.get("submodule_path")),
        "archived": False,
        "scanned": False,
        "manifest": False,
        "factory": False,
        "factory_blueprints": [],
        "agent_context": None,
        "oauth_secret": secret_states.get(nwo, "unknown"),
        "workflows_total": 0,
        "harnesses": [],
        "scheduled": [],
    }
    if nwo == cfg.get("hub_nwo"):
        row["oauth_secret"] = "hub"  # the canonical copy every rotation writes FROM
    if not nwo or row["external"]:
        return row
    try:
        repo = gh.get_repo(nwo)
        row["archived"] = bool(repo.archived)
    except Exception:
        return row
    try:
        root_names = {c.name for c in repo.get_contents("")}
    except Exception:
        root_names = set()
    row["manifest"] = MANIFEST_FILE in root_names
    # `.factory/` presence comes from the root listing already fetched (no
    # extra request); the blueprint NAMES cost one listing, only for repos
    # that actually carry the design directory.
    row["factory"] = FACTORY_DIR in root_names
    if row["factory"]:
        try:
            listing = repo.get_contents(FACTORY_DIR)
            if not isinstance(listing, list):
                listing = [listing]
            row["factory_blueprints"] = sorted(
                c.name for c in listing if c.name.endswith(BLUEPRINT_SUFFIX))
        except Exception:
            pass
    for cand in AGENT_CONTEXT_FILES:
        if cand in root_names:
            row["agent_context"] = cand
            break
    if row["agent_context"] is None:
        try:
            repo.get_contents(COPILOT_CONTEXT_PATH)
            row["agent_context"] = COPILOT_CONTEXT_PATH
        except Exception:
            pass
    try:
        listing = repo.get_contents(".github/workflows")
    except Exception:
        listing = []
    if not isinstance(listing, list):
        listing = [listing]
    files = sorted((c for c in listing if c.name.endswith((".yml", ".yaml"))),
                   key=lambda c: c.name)
    # A repo with more workflow files than the cap is read only up to it, and
    # says so: silently dropping the tail hid harnesses with no trace.
    row["workflows_listed"] = len(files)
    row["workflows_truncated"] = len(files) > cfg["inventory"]["max_workflow_files"]
    files = files[: cfg["inventory"]["max_workflow_files"]]
    shapes = kit_shapes(hub_version, repo_name=name or "")
    for entry in files:
        try:
            text = repo.get_contents(entry.path).decoded_content.decode("utf-8", "replace")
        except Exception:
            continue
        row["workflows_total"] += 1
        info = classify_workflow(entry.path, text)
        for cron in info["crons"]:
            row["scheduled"].append({
                "workflow": info["name"],
                "path": info["path"],
                "cron": cron,
                "human": describe_cron(cron),
                "est_per_day": cron_fires_per_day(cron),
                "ai": info["ai"],
            })
        if info["ai"]:
            row["harnesses"].append(harness_row(name, info, text, hub_version, shapes))
    row["scanned"] = True
    return row


def is_external(nwo: str | None, cfg: dict) -> bool:
    """Not one of the fleet's own accounts (`hub.owners`): an upstream mirror
    the hub reads about but never scans or writes to. The owners list is the
    one tools/fanout.sh uses, so "external" means the same thing to the
    inventory and to the lever it names."""
    if not nwo:
        return False
    return nwo.split("/", 1)[0] not in (cfg.get("owners") or [cfg["hub_nwo"].split("/", 1)[0]])


def harness_row(repo_name: str | None, info: dict, text: str, hub_version: str | None,
                shapes: dict[str, str]) -> dict:
    """One inventory row from a classified workflow. The first block is the
    consumed interface (harness-registry/v1); everything after `factory` was
    added with the standard and is what `grade_harness` reads."""
    return {
        "workflow": info["name"],
        "path": info["path"],
        "kind": info["kind"],
        "triggers": info["triggers"],
        "crons": info["crons"],
        "action_ref": info.get("action_ref"),
        "auth": info.get("auth"),
        "model": info.get("model"),
        "max_turns": info.get("max_turns"),
        "max_budget_usd": info.get("max_budget_usd"),
        "kit": info.get("kit"),
        "kit_status": kit_status(info.get("kit"), hub_version),
        "mention_handler": bool(info.get("mention_handler")),
        "switch": info.get("switch"),
        "factory": info.get("factory"),
        "id": harness_id(repo_name or "", info["path"]),
        "route": info.get("route"),
        "routes": info.get("routes") or [],
        "model_source": info.get("model_source"),
        "kit_pristine": kit_pristine(info["path"], text, shapes),
        "author_gate": info.get("author_gate"),
        "least_privilege": bool(info.get("least_privilege")),
        "timeout": bool(info.get("timeout")),
    }


def ensure_hub(registry: list[dict], cfg: dict) -> list[dict]:
    """The registry lists the PROJECTS; the hub itself is not one of them —
    yet it runs the fleet's heaviest scheduled agents (doctor, pipeline tiers,
    evolution). An inventory of "all the harnesses across all the repos" that
    omitted the control plane's own would be lying by omission, so the hub is
    injected as a scan target when the registry doesn't already carry it."""
    hub_nwo = cfg["hub_nwo"]
    url = f"https://github.com/{hub_nwo}"
    if any((p.get("repo_url") or "").rstrip("/").removesuffix(".git") == url
           for p in registry):
        return list(registry)
    hub_row = {"name": hub_nwo.split("/", 1)[-1], "repo_url": url,
               "category": "dash", "status": "active"}
    return [hub_row] + list(registry)


def collect_fleet(gh, registry: list[dict], cfg: dict, rotation: dict,
                  hub_version: str | None) -> list[dict]:
    secret_states = rotation_secret_states(rotation)
    rows = []
    for project in ensure_hub(registry, cfg):
        sys.stderr.write(f"  harness · {project.get('name')}\n")
        rows.append(scan_repo(gh, project, cfg, secret_states, hub_version))
    return rows


# --------------------------------------------------------------------------- #
# assembly
# --------------------------------------------------------------------------- #
def finalize(repos: list[dict], cfg: dict, hub_version: str | None, ai_usage: dict,
             actions_usage: dict, scan_mode: str, scanned_at: str | None,
             now: dt.datetime) -> dict:
    join_usage(repos, ai_usage, actions_usage)
    # Deployability is a registry fact, so stamp it in BOTH modes — a reused
    # scan predates the field, and without it the board, the attention queue
    # and `--gaps` would disagree about which gaps the fan-out can close.
    subs = submodule_names()
    for r in repos:
        r["submodule"] = r["repo"] in subs
        # Ownership is a contract fact (hub.owners), so it is stamped in both
        # modes too: a scan taken when only bamr87/ counted as the fleet's own
        # must not keep calling an organization's repo an external mirror.
        r["external"] = is_external(r.get("nwo"), cfg)
        r["deployable"] = is_deployable(r)
        r["est_scheduled_ai_per_day"] = repo_schedule_load(r)
        evaluate_coverage(r, cfg)
        # The standard is graded here, in both modes, from the facts the scan
        # stored — so retuning `harnesses.standard` regrades the fleet offline.
        for h in r.get("harnesses") or []:
            h.setdefault("id", harness_id(r.get("repo") or "", h.get("path") or ""))
            h["standard"] = grade_harness(h, cfg)
            h["lever"] = choose_lever(h, r, cfg)
    throughput = build_throughput(repos, cfg, ai_usage)
    trends = build_trends(ai_usage, actions_usage, cfg)
    catalog = build_catalog(repos, cfg)
    attention = build_attention(repos, throughput, trends, cfg, catalog)

    calendar = []
    for r in repos:
        for s in r.get("scheduled") or []:
            calendar.append({"repo": r["repo"], **s})
    # AI crons first, then heaviest standing load — the operator's reading order.
    calendar.sort(key=lambda s: (not s["ai"], -(s.get("est_per_day") or 0),
                                 s["repo"], s["path"]))
    calendar = calendar[: cfg["inventory"]["schedule_limit"]]

    graded = [r for r in repos if not (r.get("coverage") or {}).get("exempt")]
    # Live harnesses only: a workflow in an archived repo is listed (lever:
    # retire) but is not an AI workflow the fleet runs.
    all_harnesses = [h for r in repos if not is_retired(r) for h in r.get("harnesses") or []]
    totals = {
        "repos": len(repos),
        "repos_scanned": sum(1 for r in repos if r.get("scanned")),
        "repos_with_ai": sum(1 for r in repos if r.get("harnesses")),
        "ai_workflows": len(all_harnesses),
        "mention_handlers": sum(1 for h in all_harnesses if h.get("mention_handler")),
        "scheduled_agents": sum(1 for h in all_harnesses if h.get("kind") == "scheduled-agent"),
        "scheduled_workflows": sum(len(r.get("scheduled") or []) for r in repos),
        "est_scheduled_ai_per_day": throughput["est_scheduled_ai_per_day"],
        "baseline_ok": sum(1 for r in graded if (r.get("coverage") or {}).get("ok")),
        "baseline_gaps": sum(1 for r in graded if not (r.get("coverage") or {}).get("ok")),
        "kit_upgradeable": sum(1 for h in all_harnesses if upgradeable(h)),
        "factory_repos": sum(1 for r in repos if r.get("factory")),
        "factory_lines": sum(1 for h in all_harnesses if h.get("factory")),
        "scheduled_switched": sum(1 for h in all_harnesses
                                  if h.get("kind") == "scheduled-agent" and h.get("switch")),
        "attention": len(attention),
        "harnesses_graded": catalog["graded"],
        "harnesses_conformant": catalog["conformant"],
        "harnesses_retired": catalog["retired"],
        "repos_truncated": sum(1 for r in repos if r.get("workflows_truncated")),
    }
    standard = cfg["standard"]
    return {
        "schema": SCHEMA_MARKER,
        "generated_at": now.strftime("%Y-%m-%d %H:%M UTC"),
        "scan": {"mode": scan_mode, "scanned_at": scanned_at},
        "contract": {
            "kit": cfg["kit"],
            "kit_version": hub_version,
            "baseline": cfg["baseline"],
            "exempt": cfg["exempt"],
            "throughput": cfg["throughput"],
            "budget": cfg["budget"],
            "standard": {
                "version": standard["version"],
                "allowed_models": cfg["allowed_models"],
                "routes": standard["routes"],
                "controls": standard["controls"],
            },
        },
        "totals": totals,
        "catalog": catalog,
        "trends": trends,
        "throughput": throughput,
        "attention": attention,
        "schedule": calendar,
        "repos": sorted(repos, key=lambda r: (
            (r.get("coverage") or {}).get("ok", True), -len(r.get("harnesses") or []),
            r.get("repo") or "")),
        "note": (
            "Fleet AI-harness + schedule inventory: deployments, crons, throughput, "
            "and cost trends graded against _data/fleet.yml `harnesses:` "
            "(docs/HARNESS-OPS.md). Read-only observation — the fixes belong to "
            "fanout.yml kit=harness (deploy/upgrade), token-rotation (secrets), and the "
            "fleet-pulse doctor (failures). Consumed by GitFactory's Fleet Studio "
            "(bamr87/gitorio specs/012) — `schema` is the compatibility marker: "
            "additive changes are free, renames/removals bump it."
        ),
    }


def submodule_names(projects_path: Path | None = None) -> set[str]:
    """Registry entries mounted as submodules of the hub.

    Reported on the board because it says where a repo's working tree lives,
    NOT because it gates the fan-out — see is_deployable() for that."""
    path = Path(projects_path or actions_analytics.REGISTRY)
    if not path.exists():
        return set()
    try:
        with path.open() as fh:
            # the registry is a bare list; load_yaml() is dict-only and would
            # silently flatten it to {} — hence the direct read.
            data = yaml.safe_load(fh) or []
    except yaml.YAMLError:
        return set()
    projects = data.get("projects") if isinstance(data, dict) else data
    return {p["name"] for p in (projects or [])
            if isinstance(p, dict) and p.get("submodule_path") and p.get("name")}


def is_deployable(row: dict) -> bool:
    """Can `tools/fanout.sh` open a kit PR against this repo?

    Two conditions, and neither is "is it a submodule": the engine clones the
    target fresh from GitHub, so a mount buys nothing. It needs an upstream we
    own (the external-upstream guard refuses anything outside github.com/bamr87)
    and a repo worth writing to (archived repos are read-only in practice).
    Registry entries without a submodule_path resolve through the registry.
    """
    return bool(row.get("nwo")) and not row.get("external") and not row.get("archived")


def gap_candidates(registry_path: Path) -> list[dict]:
    """Every repo whose coverage the KIT could close, deployable or not."""
    data = load_yaml(registry_path)
    out = []
    for r in data.get("repos") or []:
        missing = set((r.get("coverage") or {}).get("missing") or [])
        behind = any(upgradeable(h) for h in r.get("harnesses") or [])
        if r.get("repo") and ((missing & {"mention-handler", "agent-context"}) or behind):
            out.append(r)
    return out


def fanout_gaps(registry_path: Path, projects_path: Path | None = None) -> list[str]:
    """Repo names the fan-out can actually help: a kit-deployable baseline gap
    (mention handler / agent context) or an upgradeable machine seed. Secret
    gaps are token-rotation's lane and are deliberately not deploy targets.

    The filter is DEPLOYABILITY, not submodule membership. It was the latter
    while fanout.sh resolved --target through .gitmodules alone: emitting an
    unmounted repo produced a target list the deploy lever silently no-opped
    on, the whole `--gaps` run printing `skip X: not in .gitmodules` and
    exiting 0. The engine now falls back to the registry, so those repos are
    real targets; what stays excluded is what the engine still refuses —
    external upstreams and archived repos — which surface as a
    `gap-not-deployable` attention item instead."""
    return [r["repo"] for r in gap_candidates(registry_path) if is_deployable(r)]


# --------------------------------------------------------------------------- #
# entry point
# --------------------------------------------------------------------------- #
def run(args: argparse.Namespace) -> int:
    out_path = Path(args.out)
    if args.gaps:
        gaps = fanout_gaps(out_path)
        if not out_path.exists():
            sys.stderr.write(
                f"harnesses: no committed inventory at {out_path} — run "
                "`dash harnesses` first; emitting no targets.\n")
        for name in gaps:
            print(name)
        return 0

    now = dt.datetime.now(dt.timezone.utc)
    cfg = load_config(Path(args.fleet))
    hub_version = hub_kit_version()
    ai_usage = load_yaml(Path(args.ai_usage))
    actions_usage = load_yaml(Path(args.actions_usage))
    rotation = load_yaml(Path(args.rotation))

    token = None if args.offline else actions_analytics.resolve_token()
    repos: list[dict] = []
    scan_mode, scanned_at = "none", None
    if token:
        try:
            from github import Github, Auth
        except ImportError:
            sys.stderr.write("harnesses scan requires PyGithub: pip install PyGithub\n")
            token = None
        if token:
            gh = Github(auth=Auth.Token(token), per_page=100)
            with actions_analytics.REGISTRY.open() as fh:
                registry = yaml.safe_load(fh) or []
            repos = collect_fleet(gh, registry, cfg, rotation, hub_version)
            scan_mode, scanned_at = "live", now.strftime("%Y-%m-%d %H:%M UTC")
    if not repos:
        # No credentials (or --offline): reuse the previous committed scan so
        # the offline analytics still refresh — same degrade-don't-die posture
        # as every other gather step.
        prior = load_yaml(out_path)
        repos = prior.get("repos") or []
        scan_mode = "reused" if repos else "none"
        scanned_at = (prior.get("scan") or {}).get("scanned_at") or prior.get("generated_at")
        if not repos:
            sys.stderr.write(
                "harnesses: no GitHub token and no prior inventory to reuse — "
                "writing contract + trends only.\n")

    out = finalize(repos, cfg, hub_version, ai_usage, actions_usage,
                   scan_mode, scanned_at, now)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    with out_path.open("w") as fh:
        fh.write(
            "# GENERATED by .github/scripts/dash-gen (harness_registry) — refreshed "
            "daily by fleet-pulse.yml. Edit the generator, not this file.\n"
        )
        yaml.safe_dump(out, fh, sort_keys=False, allow_unicode=True)

    t = out["totals"]
    if not args.quiet:
        sys.stderr.write(
            f"Wrote {out_path} — {t['ai_workflows']} AI workflows in "
            f"{t['repos_with_ai']}/{t['repos_scanned']} repos (scan: {scan_mode}), "
            f"{t['scheduled_workflows']} crons, "
            f"~{t['est_scheduled_ai_per_day']}/day scheduled AI, "
            f"{t['harnesses_conformant']}/{t['harnesses_graded']} on the standard, "
            f"{t['attention']} attention item(s)\n")
        for lever, count in (out["catalog"]["by_lever"] or {}).items():
            if lever != "none":
                sys.stderr.write(f"  ↻ {lever}: {count}\n")
        for item in out["attention"][:5]:
            where = f" [{item['repo']}]" if item.get("repo") else ""
            sys.stderr.write(f"  ⚠ {item['kind']}{where}: {item['summary']}\n")

    gh_out = os.environ.get("GITHUB_OUTPUT")
    if gh_out:
        with open(gh_out, "a") as fh:
            fh.write(f"ai_workflows={t['ai_workflows']}\n")
            fh.write(f"attention_count={t['attention']}\n")
    return 0


def add_arguments(parser: argparse.ArgumentParser) -> None:
    parser.add_argument("--fleet", default=str(FLEET_DEFAULT),
                        help="fleet.yml (harnesses: contract)")
    parser.add_argument("--ai-usage", default=str(AI_USAGE_DEFAULT),
                        help="ai_usage.yml input (cost joins + trends)")
    parser.add_argument("--actions-usage", default=str(ACTIONS_DEFAULT),
                        help="actions_usage.yml input (run joins + trends)")
    parser.add_argument("--rotation", default=str(ROTATION_DEFAULT),
                        help="token_rotation.yml input (secret presence)")
    parser.add_argument("--out", default=str(OUT_DEFAULT), help="output path")
    parser.add_argument("--days", type=int, default=14,
                        help="accepted for symmetry with the other gathers; the "
                             "joined windows are whatever the committed ledgers carry")
    parser.add_argument("--offline", action="store_true",
                        help="skip the GitHub scan; reuse the previous committed scan")
    parser.add_argument("--gaps", action="store_true",
                        help="print fan-out-deployable gap repos from the committed "
                             "inventory, one per line (offline; feeds fanout.yml kit=harness)")
    parser.add_argument("--quiet", action="store_true", help="suppress the summary lines")
    parser.set_defaults(func=run)


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__)
    add_arguments(ap)
    raise SystemExit(run(ap.parse_args()))
